// Takes a lane of { domain, client } entries and emits one item per valid domain.
// The scan node runs items one after another, so each lane scans its domains sequentially.
// Re-checked here because any caller can hand this workflow domains, and they reach a shell command.
const hostname = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const lane = $input.first().json.domains;
const seen = new Set();
const out = [];
for (const entry of Array.isArray(lane) ? lane : []) {
  const domain = String(entry?.domain ?? '').trim().toLowerCase();
  if (!hostname.test(domain) || seen.has(domain)) continue;
  seen.add(domain);
  out.push({ json: { domain, client: String(entry?.client ?? '').trim() || null } });
}
return out;

// One item per confirmed takeover finding. No findings means no items, so nothing downstream runs.
// Failed scans are skipped here and reported by Find Failed Scans, so one bad domain doesn't block the lane.
// The scan node only returns command output, so the client is looked up by root domain.
const clients = new Map($('Validate Lane').all().map(i => [i.json.domain, i.json.client ?? null]));
const now = new Date().toISOString();
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  if (item.json.error) continue;
  let run;
  try {
    run = JSON.parse(item.json.stdout);
  } catch (e) {
    continue;
  }
  if (run.error) continue;
  for (const f of run.findings ?? []) {
    const host = String(f.host ?? '').replace(/^[a-z]+:\/\//i, '').split(/[/:]/)[0].toLowerCase();
    const key = `${host}|${f.template}`;
    if (!host || seen.has(key)) continue;
    seen.add(key);
    out.push({ json: {
      finding_key: key,
      domain: run.domain,
      host,
      cname: run.cnames?.[host] ?? '',
      template_id: f.template ?? '',
      name: f.name ?? '',
      severity: f.severity ?? '',
      matched_at: f.matched ?? '',
      evidence_dir: run.output,
      status: 'new',
      first_seen: now,
      client: clients.get(run.domain) ?? null
    } });
  }
}
return out;

// One Discord embed per host. Groups every new detection for the host, colours by worst severity,
// separates confirmed service fingerprints from plain dangling CNAMEs, and tags the client.
const RANK = { critical: 4, high: 3, medium: 2, low: 1, info: 0, unknown: -1 };
const COLOUR = { critical: 0x9B111E, high: 0xE74C3C, medium: 0xF39C12, low: 0x3498DB, info: 0x95A5A6, unknown: 0x7F8C8D };
const cut = (s, n) => { s = String(s ?? ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const code = s => '`' + String(s).replace(/`/g, "'") + '`';
const title = s => s.charAt(0).toUpperCase() + s.slice(1);

const hosts = new Map();
for (const { json: f } of $input.all()) {
  if (!hosts.has(f.host)) hosts.set(f.host, { ...f, detections: [] });
  const h = hosts.get(f.host);
  h.detections.push({ id: f.template_id, name: f.name, severity: String(f.severity || 'unknown').toLowerCase(), matched: f.matched_at });
}

return [...hosts.values()].map(h => {
  const worst = h.detections.reduce((w, d) => (RANK[d.severity] ?? -1) > (RANK[w] ?? -1) ? d.severity : w, 'unknown');
  const danglingOnly = h.detections.every(d => /dangling|servfail/i.test(d.id));
  const client = String(h.client ?? '').trim();
  const cname = h.cname || 'none recorded';
  const tag = client ? `[${client}] ` : '';
  const headline = tag + (danglingOnly ? `⚠️ Dangling CNAME · ${h.host}` : `🎯 Possible takeover · ${h.host}`);
  const description = danglingOnly
    ? `${code(h.host)} points at ${code(cname)}, which no longer resolves. Check whether that target name can be registered by anyone.`
    : `nuclei matched a takeover fingerprint on ${code(h.host)}. The service behind ${code(cname)} may let someone claim this hostname.`;
  const detections = h.detections
    .map(d => `• **${cut(d.name || d.id, 80)}** · ${title(d.severity)}\n  ${code(d.id)}`)
    .join('\n');
  const matched = [...new Set(h.detections.map(d => d.matched).filter(Boolean))].map(code).join('\n');
  return { json: {
    host: h.host,
    client: client || null,
    embed: {
      title: cut(headline, 256),
      url: `https://${h.host}`,
      description: cut(description, 1000),
      color: COLOUR[worst] ?? COLOUR.unknown,
      fields: [
        { name: 'Severity', value: title(worst), inline: true },
        { name: 'Root domain', value: code(h.domain), inline: true },
        { name: 'Client', value: cut(client || 'None', 1024), inline: true },
        { name: 'CNAME target', value: cut('```\n' + cname + '\n```', 1024) },
        { name: 'What matched', value: cut(detections, 1024) },
        { name: 'Matched at', value: cut(matched || code(h.host), 1024) },
        { name: 'Evidence', value: cut(code(h.evidence_dir), 1024) }
      ],
      footer: { text: `Offensive N8N · Subdomain Takeover Monitor · ${h.detections.length} detection${h.detections.length === 1 ? '' : 's'}` },
      timestamp: h.first_seen
    }
  } };
});

// One Discord embed per domain whose scan errored or returned unusable output.
// The scan node emits one item per lane entry, so the index maps back to the domain.
const lane = $('Validate Lane').all();
const cut = (s, n) => { s = String(s ?? ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const out = [];
$input.all().forEach((item, i) => {
  const { domain = 'unknown', client = null } = lane[i]?.json ?? {};
  let reason = null;
  if (item.json.error) {
    const e = item.json.error;
    reason = typeof e === 'string' ? e : (e.message ?? JSON.stringify(e));
  } else {
    try {
      const run = JSON.parse(item.json.stdout);
      if (run.error) reason = `Scan refused: ${run.error}`;
    } catch (e) {
      reason = `Output was not JSON (exit ${item.json.exitCode}): ${item.json.stderr || item.json.stdout || 'no output'}`;
    }
  }
  if (!reason) return;
  const tag = client ? `[${client}] ` : '';
  out.push({ json: {
    domain,
    client,
    reason,
    embed: {
      title: cut(`${tag}❌ Scan failed · ${domain}`, 256),
      description: 'The takeover scan for this domain did not complete, so it was skipped this run. Other domains in the lane were still processed.',
      color: 0x7F8C8D,
      fields: [
        { name: 'Client', value: cut(client || 'None', 1024), inline: true },
        { name: 'Error', value: cut('```\n' + reason + '\n```', 1024) },
        { name: 'Logs', value: cut('`/opt/loot/takeover/' + domain + '/<latest>/*.log`', 1024) }
      ],
      footer: { text: 'Offensive N8N · Subdomain Takeover Monitor' },
      timestamp: new Date().toISOString()
    }
  } });
});
return out;
